package org.ssssssss.magicapi.iot.transport.websocket; import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties("iot.transports.websocket") public class WebSocketTransportProperties { private boolean enabled; private String host="0.0.0.0"; private int port=19002; private String path="/iot"; private int maxFrameSize=65536; private String protocolId="raw"; public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getHost(){return host;}public void setHost(String v){host=v;}public int getPort(){return port;}public void setPort(int v){port=v;}public String getPath(){return path;}public void setPath(String v){path=v;}public int getMaxFrameSize(){return maxFrameSize;}public void setMaxFrameSize(int v){maxFrameSize=v;}public String getProtocolId(){return protocolId;}public void setProtocolId(String v){protocolId=v;}}
